namespace EnterpriseKnowledgeAssistant.Api.Infrastructure.Storage;

public sealed record StoredObject(string StorageKey, long SizeBytes, string Sha256);

/// <summary>
/// Private object storage for document binaries (gap G32). Keys are opaque and generated by the server;
/// new uploads land in quarantine until scanned. No provider is chosen or registered yet.
/// </summary>
public interface IDocumentStorage
{
    Task<StoredObject> PutQuarantinedAsync(Stream content, string contentType, CancellationToken cancellationToken = default);

    Task<Uri> CreateDownloadUrlAsync(string storageKey, TimeSpan lifetime, CancellationToken cancellationToken = default);

    Task DeleteAsync(string storageKey, CancellationToken cancellationToken = default);
}
